// Compliance explorer — reads data/catalog.json generated by tools/build.py.
const $ = (s) => document.querySelector(s);
const esc = (v) => String(v ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);
const VER = { primary: "✓ primary", secondary: "◐ secondary", unverified: "⚠ unverified" };
const STATUS = { "in-force": "In force", "in-force-phased": "In force (phased)", phased: "Phased", pending: "Pending — not law", voluntary: "Voluntary", none: "No specific rule", proposed: "Proposed" };
const GROUP = { horizontal: "AI law and frameworks", data_protection: "Data protection", cyber: "Cybersecurity" };
const GATE = { apra_regulated: "APRA-regulated entities", nz_registered_bank: "NZ registered banks ≥ NZ$10bn", mas_regulated: "MAS-regulated FIs", critical_infrastructure: "critical infrastructure operators" };

let cat, fwById, ctlById, vendors;

async function main() {
  cat = await (await fetch("data/catalog.json", { cache: "no-store" })).json();
  fwById = Object.fromEntries(cat.frameworks.map((f) => [f.id, f]));
  ctlById = Object.fromEntries(cat.controls.map((c) => [c.id, c]));
  vendors = Object.keys(cat.vendors).sort();
  $("#asof").textContent = cat.asOf;

  const countries = [...new Map(cat.profiles.map((p) => [p.country, p.country_name])).entries()];
  const sectors = [...new Map(cat.profiles.map((p) => [p.sector, p.sector_name])).entries()];
  $("#country").innerHTML = countries.map(([k, v]) => `<option value="${k}">${esc(v)}</option>`).join("");
  $("#sector").innerHTML = sectors.map(([k, v]) => `<option value="${k}">${esc(v)}</option>`).join("");
  const params = new URLSearchParams(location.hash.slice(1));
  if (params.get("c")) $("#country").value = params.get("c");
  if (params.get("s")) $("#sector").value = params.get("s");
  $("#country").addEventListener("change", renderProfile);
  $("#sector").addEventListener("change", renderProfile);

  renderStats();
  renderProfile();
  renderCrosswalk();
  renderVendors();
}

function renderStats() {
  const inst = new Set(cat.profiles.flatMap((p) => p.instruments.map((i) => i.id)));
  const impl = Object.values(cat.vendors).reduce((n, v) => n + (v.implements || []).length, 0);
  const tiles = [
    { n: cat.profiles.length, l: "country × sector profiles" },
    { n: cat.frameworks.length, l: "frameworks and national laws" },
    { n: inst.size, l: "instruments catalogued" },
    { n: impl, l: "vendor control implementations" },
  ];
  $("#stats").innerHTML = tiles.map((t) => `<div class="stat"><div class="n">${t.n}</div><div class="l">${esc(t.l)}</div></div>`).join("");
}

function coverage(cid) {
  return vendors.map((v) => {
    const vp = cat.vendors[v];
    if ((vp.implements || []).some((i) => i.control === cid)) return "●";
    if ((vp.gaps || []).some((g) => g.control === cid)) return "○";
    return "·";
  }).join(" ");
}

function renderProfile() {
  const c = $("#country").value, s = $("#sector").value;
  const p = cat.profiles.find((x) => x.country === c && x.sector === s);
  if (!p) return;
  history.replaceState(null, "", `#c=${c}&s=${s}`);
  $("#profile-title").textContent = `${p.country_name} — ${p.sector_name}`;
  $("#profile-link").href = `https://github.com/caiotk/ai-governance-compliance-as-code/blob/main/${p.path}`;

  const fws = p.frameworks.map((id) => {
    const f = fwById[id];
    const gated = f.applies_when ? `<span class="gate">${esc(GATE[f.applies_when.entity_type] || f.applies_when.entity_type)} only</span>` : "";
    const status = f.baseline ? "baseline (voluntary)" : (STATUS[f.status] || f.status);
    return `<li class="${f.applies_when ? "gated" : ""}"><a href="${esc(f.url)}">${esc(f.name.split(" — ")[0])}</a><span class="gate">${esc(status)}</span>${gated}</li>`;
  }).join("");

  const groups = {};
  for (const i of p.instruments) {
    const key = GROUP[i.group] || `Sector rules: ${p.sector_name}`;
    (groups[key] ||= []).push(i);
  }
  const inst = Object.entries(groups).map(([g, items]) => `<div class="inst-group"><h4>${esc(g)}</h4>${items.map((i) => `
    <div class="inst"><div><span class="nm">${esc(i.name)}</span><span class="status ${esc(i.status)}">${esc(STATUS[i.status] || i.status)}</span>
      <div class="meta">${esc(i.citation || "")}${i.effective ? " · " + esc(i.effective) : ""} · drives ${i.controls.join(", ")}</div></div>
      <a class="ver ${esc(i.verification)}" href="${esc(i.url)}">${VER[i.verification]}</a></div>`).join("")}</div>`).join("");

  const sector = cat.sectors.find((x) => x.id === s);
  const triggers = sector.high_risk_triggers.filter((t) => t.jurisdictions === "all" || t.jurisdictions.includes(c)).map((t) => `<li>${esc(t.text)}</li>`).join("");

  const ctls = p.required_controls.map((cid) => {
    const ctl = ctlById[cid];
    const drv = Object.keys(ctl.mappings).filter((fw) => p.frameworks.includes(fw)).map((fw) => fwById[fw].name.split(" — ")[0].split(" (")[0]);
    const emph = p.emphasised_controls.includes(cid);
    return `<div class="ctl ${emph ? "emph" : ""}"><div class="id">${cid}${emph ? " ★" : ""}</div><div class="t">${esc(ctl.title)}</div><div class="drv">${esc(drv.join(" · "))}</div><div class="cov">${coverage(cid)}</div></div>`;
  }).join("");

  $("#profile-body").innerHTML = `
    <h4>Frameworks applied</h4><ul class="fw-list">${fws}</ul>
    <h4>Pushes a system into a higher risk tier here</h4><ul>${triggers}</ul>
    ${inst}
    <h4 style="margin-top:22px">Required controls <span class="muted">(coverage: ${vendors.map((v) => v.replace("-", " ")).join(" · ")})</span></h4>
    <div class="ctl-grid">${ctls}</div>`;
}

function renderCrosswalk() {
  const fws = cat.frameworks.filter((f) => !f.id.match(/^(br|cl|ar|jp|sg)-/));
  const head = `<thead><tr><th scope="col">Control</th>${fws.map((f) => `<th scope="col" class="rot" title="${esc(f.name)}">${esc(f.id)}</th>`).join("")}</tr></thead>`;
  const rows = cat.controls.map((c) => `<tr><td><button type="button" class="xw-btn" data-id="${c.id}"><span class="id" style="font-family:var(--mono);color:var(--accent);margin-right:8px">${c.id}</span>${esc(c.title)}</button></td>${fws.map((f) => `<td>${c.mappings[f.id] ? '<span class="dot impl">●</span>' : ""}</td>`).join("")}</tr>`).join("");
  $("#xw").innerHTML = head + `<tbody>${rows}</tbody>`;
  document.querySelectorAll(".xw-btn").forEach((b) => b.addEventListener("click", () => {
    const c = ctlById[b.dataset.id];
    $("#xw-detail").innerHTML = `<article class="detail-card"><div class="detail-head"><div><h3>${c.id} — ${esc(c.title)}</h3><p>${esc(c.objective)}</p></div></div>
      <ul class="clauses">${Object.entries(c.mappings).map(([fw, refs]) => `<li><b>${esc(fwById[fw].name.split(" — ")[0])}:</b> ${refs.map(esc).join("; ")}</li>`).join("")}</ul>
      <p class="muted" style="margin-top:12px">Vendor coverage: ${vendors.map((v, i) => `${esc(v)} ${coverage(c.id).split(" ")[i]}`).join(" · ")}</p></article>`;
    $("#xw-detail").scrollIntoView({ behavior: "smooth", block: "nearest" });
  }));
}

function renderVendors() {
  const head = `<thead><tr><th scope="col">Control</th>${vendors.map((v) => `<th scope="col">${esc(v)}</th>`).join("")}</tr></thead>`;
  const rows = cat.controls.map((c) => `<tr><td><span style="font-family:var(--mono);color:var(--accent);margin-right:8px">${c.id}</span>${esc(c.title)}</td>${vendors.map((v) => {
    const vp = cat.vendors[v];
    const impl = (vp.implements || []).find((i) => i.control === c.id);
    const gap = (vp.gaps || []).find((g) => g.control === c.id);
    const t = impl ? impl.summary : gap ? gap.note : "";
    return `<td title="${esc(t)}">${impl ? '<button type="button" class="v-btn dot impl" data-v="' + v + '" style="justify-content:center">●</button>' : gap ? '<button type="button" class="v-btn dot gap" data-v="' + v + '" style="justify-content:center">○</button>' : "·"}</td>`;
  }).join("")}</tr>`).join("");
  $("#vendor-matrix").innerHTML = head + `<tbody>${rows}</tbody>`;
  document.querySelectorAll(".v-btn").forEach((b) => b.addEventListener("click", () => showVendor(b.dataset.v)));
}

function showVendor(v) {
  const vp = cat.vendors[v];
  $("#vendor-detail").innerHTML = `<article class="detail-card vendor-card"><div class="detail-head"><div><h3>${esc(vp.name)}</h3>
      <p class="tools">${(vp.native_tools || []).map((t) => `<a href="${esc(t.url)}">${esc(t.name)}</a>`).join("")}</p></div>
      <a class="btn" href="https://github.com/caiotk/ai-governance-compliance-as-code/tree/main/vendors/${v}">Open the pack</a></div>
    <h4>Implements</h4><ul>${(vp.implements || []).map((i) => `<li><b>${i.control}</b> ${esc(i.summary)}</li>`).join("")}</ul>
    <h4>Gaps</h4><ul>${(vp.gaps || []).map((g) => `<li><b>${g.control}</b> ${esc(g.note)}</li>`).join("")}</ul>
    ${(vp.attestations || []).length ? `<h4>Attestations</h4><ul>${vp.attestations.map((a) => `<li><a href="${esc(a.url)}">${esc(a.name)}</a>${a.scope ? " — " + esc(a.scope) : ""}</li>`).join("")}</ul>` : ""}</article>`;
  $("#vendor-detail").scrollIntoView({ behavior: "smooth", block: "nearest" });
}

main().catch((e) => { $("#profile-body").innerHTML = `<p class="error">Could not load data/catalog.json: ${esc(e.message)}</p>`; });
